// src/pages/Dashboard.tsx

import React, { useEffect, useState } from "react";
import {
  Box,
  Paper,
  Typography,
  CircularProgress,
  Alert,
  Chip,
  Divider,
} from "@mui/material";

import {
  People,
  TrendingUp,
  Business,
  Inventory,
  PointOfSale,
  Warning,
  AttachMoney,
} from "@mui/icons-material";

import { useAuth } from "../contexts/AuthContext";
import { useCompany } from "../contexts/CompanyContext";

import {
  companyApi,
  quoteApi,
  purchaseOrderApi,
  productApi,
  salesApi,
  expenseApi,
} from "../api";

import {
  CompanyStats,
  QuoteStats,
  PurchaseOrderStats,
  ProductStats,
  SaleStats,
  ExpenseStats,
} from "../types";

import { formatCurrency } from "../utils/currency";
import { COLORS } from "../theme/colors";

/* -------------------------------------------------------
    PREMIUM KPI CARD
--------------------------------------------------------*/
const KpiCard = ({
  label,
  value,
  icon,
  subtitle,
}: {
  label: string;
  value: string | number;
  icon: React.ReactElement<{ sx?: any }>;
  subtitle?: string;
}) => {
  const ic = React.cloneElement(icon, {
    sx: { fontSize: 30, color: COLORS.textPrimary },
  });

  return (
    <Paper
      elevation={0}
      sx={{
        p: 3,
        borderRadius: 3,
        bgcolor: COLORS.surfaceAlt,
        border: `1px solid ${COLORS.border}`,
        boxShadow: `0 0 15px ${COLORS.background}`,
        transition: "0.25s",
        "&:hover": {
          borderColor: COLORS.textSecondary,
          boxShadow: `0 0 20px ${COLORS.background}`,
          transform: "translateY(-2px)",
        },
      }}
    >
      <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
        <Box
          sx={{
            width: 60,
            height: 60,
            borderRadius: 2,
            display: "grid",
            placeItems: "center",
            bgcolor: COLORS.surface,
            border: `1px solid ${COLORS.border}`,
          }}
        >
          {ic}
        </Box>

        <Box>
          <Typography sx={{ fontSize: 14, color: COLORS.textSecondary }}>
            {label}
          </Typography>

          <Typography
            sx={{
              fontSize: 30,
              fontWeight: 800,
              color: COLORS.textPrimary,
            }}
          >
            {value}
          </Typography>

          {subtitle && (
            <Typography sx={{ fontSize: 12, color: COLORS.textSecondary }}>
              {subtitle}
            </Typography>
          )}
        </Box>
      </Box>
    </Paper>
  );
};

/* -------------------------------------------------------
    MINI STAT
--------------------------------------------------------*/
const MiniStat = ({
  label,
  value,
  icon,
  color = COLORS.textSecondary,
}: {
  label: string;
  value: string | number;
  icon: React.ReactElement<{ sx?: any }>;
  color?: string;
}) => {
  const ic = React.cloneElement(icon, {
    sx: { fontSize: 22, color: COLORS.textPrimary },
  });

  return (
    <Paper
      elevation={0}
      sx={{
        p: 2,
        borderRadius: 2,
        bgcolor: COLORS.surface,
        border: `1px solid ${COLORS.border}`,
        boxShadow: `0 0 10px ${COLORS.background}`,
      }}
    >
      <Box sx={{ display: "flex", gap: 2, alignItems: "center" }}>
        {ic}
        <Box>
          <Typography sx={{ fontSize: 12, color: COLORS.textSecondary }}>
            {label}
          </Typography>

          <Typography
            sx={{ fontSize: 17, fontWeight: 700, color: COLORS.textPrimary }}
          >
            {value}
          </Typography>
        </Box>
      </Box>
    </Paper>
  );
};

/* -------------------------------------------------------
    SECTION WRAPPER
--------------------------------------------------------*/
const Section = ({ title, children }: any) => (
  <Paper
    elevation={0}
    sx={{
      p: 3,
      borderRadius: 3,
      bgcolor: COLORS.surfaceAlt,
      border: `1px solid ${COLORS.border}`,
    }}
  >
    <Typography sx={{ fontWeight: 700, color: COLORS.textPrimary, mb: 2 }}>
      {title}
    </Typography>
    {children}
  </Paper>
);

/* -------------------------------------------------------
                    DASHBOARD MAIN
--------------------------------------------------------*/
const Dashboard: React.FC = () => {
  const { user } = useAuth();
  const { company, settings } = useCompany();

  const [stats, setStats] = useState<CompanyStats | null>(null);
  const [quoteStats, setQuoteStats] = useState<QuoteStats | null>(null);
  const [poStats, setPoStats] = useState<PurchaseOrderStats | null>(null);
  const [productStats, setProductStats] = useState<ProductStats | null>(null);
  const [saleStats, setSaleStats] = useState<SaleStats | null>(null);
  const [expenseStats, setExpenseStats] = useState<ExpenseStats | null>(null);

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  const companyLabel =
    company?.name ||
    "Your Company";

  useEffect(() => {
    const load = async () => {
      try {
        setIsLoading(true);

        const [
          companyStats,
          quoteStatsData,
          poStatsData,
          productStatsData,
          saleStatsData,
          expenseStatsData,
        ] = await Promise.all([
          companyApi.getStats(),
          quoteApi.getQuoteStats(),
          purchaseOrderApi.getStats(),
          productApi.getProducts({ limit: 1 }).then((response) => ({
            totalProducts: response.pagination.total,
            totalValue: response.products.reduce((sum, p: any) => sum + (p.sellingPrice * p.stockQuantity || 0), 0),
            lowStockProducts: response.products.filter(
              (p: any) => p.stockStatus === "low_stock",
            ).length,
            outOfStockProducts: response.products.filter(
              (p: any) => p.stockStatus === "out_of_stock",
            ).length,
            totalCategories: [
              ...new Set(response.products.map((p: any) => p.category)),
            ].length,
            averagePrice: response.products.length > 0 
              ? response.products.reduce((sum, p: any) => sum + (p.sellingPrice || 0), 0) / response.products.length
              : 0,
          })),
          salesApi.getStats().catch(() => ({
            totalSales: 0,
            totalProfit: 0,
            totalCost: 0,
            totalTransactions: 0,
            averageSaleValue: 0,
          })),
          expenseApi.getStats().catch(() => ({
            totalExpenses: 0,
            totalAmount: 0,
            pendingExpenses: 0,
            paidExpenses: 0,
            reimbursedExpenses: 0,
            averageAmount: 0,
            categoryBreakdown: [],
            monthlyTrends: [],
          })),
        ]);

        setStats(companyStats);
        setQuoteStats(quoteStatsData);
        setPoStats(poStatsData);
        setProductStats(productStatsData);
        setSaleStats(saleStatsData);
        setExpenseStats(expenseStatsData);
      } catch (err: any) {
        setError("Failed to load dashboard");
      } finally {
        setIsLoading(false);
      }
    };

    load();
  }, [settings]);

  if (isLoading)
    return (
      <Box sx={{ display: "flex", justifyContent: "center", mt: 10 }}>
        <CircularProgress />
      </Box>
    );

  if (error)
    return (
      <Alert severity="error" sx={{ mt: 2 }}>
        {error}
      </Alert>
    );

  const currency = settings?.currency || "USD";

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        bgcolor: 'transparent',
        color: COLORS.textPrimary,
        p: 2,
        boxSizing: 'border-box',
        overflowX: 'hidden',
      }}
    >
      {/* HEADER */}
      <Box sx={{ mb: 4 }}>
        <Typography sx={{ fontSize: 30, fontWeight: 800 }}>
          Welcome back, {user?.firstName}
        </Typography>

        <Typography sx={{ color: COLORS.textSecondary }}>
          Company: {companyLabel}
        </Typography>

        <Typography sx={{ color: COLORS.textSecondary }}>
          Your business performance at a glance.
        </Typography>
      </Box>

      {/* KPI GRID */}
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr",
            sm: "repeat(2, 1fr)",
            md: "repeat(4, 1fr)",
          },
          gap: 3,
          mb: 4,
        }}
      >
        <KpiCard
          label="Customers"
          value={stats?.customers.totalCustomers || 0}
          icon={<People />}
        />

        <KpiCard
          label="Products"
          value={productStats?.totalProducts || 0}
          icon={<Inventory />}
          subtitle={`${productStats?.totalCategories || 0} categories`}
        />

        <KpiCard
          label="Total Sales"
          value={formatCurrency(saleStats?.totalSales || 0, currency)}
          icon={<PointOfSale />}
        />

        <KpiCard
          label="Quote Value"
          value={formatCurrency(quoteStats?.totalQuoteValue || 0, currency)}
          icon={<TrendingUp />}
          subtitle={`Avg: ${formatCurrency(
            Math.round(quoteStats?.averageValue || 0),
            currency,
          )}`}
        />
      </Box>

      {/* MAIN GRID */}
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: { xs: "1fr", md: "2fr 1fr" },
          gap: 3,
        }}
      >
        {/* LEFT SIDE */}
        <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
          <Section title="Purchase Orders">
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
                gap: 2,
              }}
            >
              <MiniStat
                label="Total POs"
                value={poStats?.totalPOs || 0}
                icon={<Business />}
                color={COLORS.textSecondary}
              />

              <MiniStat
                label="Completed"
                value={poStats?.completedPOs || 0}
                icon={<TrendingUp />}
                color={COLORS.textSecondary}
              />
            </Box>
          </Section>

          <Section title="Inventory Alerts">
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
                gap: 2,
              }}
            >
              <MiniStat
                label="Low Stock"
                value={productStats?.lowStockProducts || 0}
                icon={<Warning />}
                color={COLORS.gold}
              />
              <MiniStat
                label="Out of Stock"
                value={productStats?.outOfStockProducts || 0}
                icon={<Warning />}
                color={COLORS.danger}
              />
            </Box>
          </Section>

          <Section title="Sales Overview">
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: { xs: "1fr", sm: "repeat(3, 1fr)" },
                gap: 2,
              }}
            >
              <MiniStat
                label="Profit"
                value={formatCurrency(saleStats?.totalProfit || 0, currency)}
                icon={<AttachMoney />}
                color={COLORS.gold}
              />

              <MiniStat
                label="Avg Sale"
                value={formatCurrency(
                  saleStats?.averageSaleValue || 0,
                  currency,
                )}
                icon={<AttachMoney />}
                color={COLORS.textSecondary}
              />

              <MiniStat
                label="Transactions"
                value={saleStats?.totalTransactions || 0}
                icon={<TrendingUp />}
                color={COLORS.textSecondary}
              />
            </Box>
          </Section>

          <Section title="Expenses">
            <Box
              sx={{
                display: "grid",
                gridTemplateColumns: { xs: "1fr", sm: "1fr 1fr" },
                gap: 2,
              }}
            >
              <MiniStat
                label="Pending"
                value={expenseStats?.pendingExpenses || 0}
                icon={<Warning />}
                color={COLORS.gold}
              />

              <MiniStat
                label="Total Amount"
                value={formatCurrency(expenseStats?.totalAmount || 0, currency)}
                icon={<AttachMoney />}
                color={COLORS.textSecondary}
              />
            </Box>
          </Section>
        </Box>

        {/* RIGHT COLUMN */}
        <Box sx={{ display: "flex", flexDirection: "column", gap: 3 }}>
          <Section title="Quote Status">
            <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap" }}>
              <Chip
                label={`Draft: ${quoteStats?.draftQuotes || 0}`}
                sx={{ bgcolor: COLORS.surface, color: COLORS.textPrimary }}
              />
              <Chip 
                label={`Sent: ${quoteStats?.sentQuotes || 0}`}
                sx={{ 
                  bgcolor: COLORS.accent, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
              <Chip 
                label={`Viewed: ${quoteStats?.viewedQuotes || 0}`}
                sx={{ 
                  bgcolor: COLORS.gold, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
              <Chip 
                label={`Accepted: ${quoteStats?.acceptedQuotes || 0}`}
                sx={{ 
                  bgcolor: COLORS.gold, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
              <Chip 
                label={`Rejected: ${quoteStats?.rejectedQuotes || 0}`}
                sx={{ 
                  bgcolor: COLORS.danger, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
            </Box>
          </Section>

          <Section title="PO Status">
            <Box sx={{ display: "flex", gap: 1, flexWrap: "wrap" }}>
              <Chip label={`Draft: ${poStats?.draftPOs || 0}`} sx={{ bgcolor: COLORS.surface }} />
              <Chip 
                label={`Sent: ${poStats?.sentPOs || 0}`}
                sx={{ 
                  bgcolor: COLORS.accent, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
              <Chip 
                label={`Confirmed: ${poStats?.confirmedPOs || 0}`}
                sx={{ 
                  bgcolor: COLORS.gold, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
              <Chip 
                label={`Completed: ${poStats?.completedPOs || 0}`}
                sx={{ 
                  bgcolor: COLORS.gold, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
              <Chip 
                label={`Cancelled: ${poStats?.cancelledPOs || 0}`}
                sx={{ 
                  bgcolor: COLORS.danger, 
                  color: COLORS.background,
                  '& .MuiChip-label': {
                    color: COLORS.background
                  }
                }} 
              />
            </Box>
          </Section>

          <Section title="Customer Value">
            <MiniStat
              label="Total Customer Value"
              value={formatCurrency(
                stats?.customers.totalValue || 0,
                currency,
              )}
              icon={<People />}
              color={COLORS.textSecondary}
            />

            <Divider sx={{ my: 2, borderColor: COLORS.border }} />

            <Typography sx={{ color: COLORS.textSecondary, fontSize: 13 }}>
              From {stats?.customers.totalCustomers || 0} customers
            </Typography>
          </Section>
        </Box>
      </Box>
    </Box>
  );
};

export default Dashboard;